insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4cbdb881-da9c-47a5-bedb-19e0456a3896', 'fr', 'Qu’est-ce qui rend un toucher juste et pas agressif ?', '["Il est ajusté à son niveau de confort et à la complicité déjà créée", "Il est bref et léger, ni prolongé ni appuyé", "Il arrive dans des moments naturels, quand elle rit ou appuie un propos", "Toutes les réponses ci-dessus"]'::jsonb, 'Le toucher est agréable quand il correspond à la complicité, reste léger et arrive dans des moments naturels.')
