insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4f400953-0471-468b-911c-2009c87a96ac', 'fr', 'La conversation est amusante et elle rit. Elle repart naturellement. Que dois-tu en penser ?', '["C’est un échec, parce que je n’ai pas eu son numéro", "L’échange a été trop court, j’ai échoué", "C’est une réussite, parce qu’on a tous les deux apprécié le moment"]'::jsonb, 'Le but, c’est un bon moment partagé, quelle que soit la suite.')
