insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('50183c21-27bd-480c-971a-891eac026c00', 'fr', 'Elle dit : « Les mecs m’offrent toujours des verres. » Que pourrais-tu dire ensuite pour montrer que tu n’es pas impressionné d’emblée ?', '["« Seulement si tu paies la prochaine tournée. »", "« Laisse-moi t’en offrir un, alors. »", "« Ça se comprend, tu as du charme. »", "« C’est quoi, ta boisson préférée ? »"]'::jsonb, 'Un défi ludique plutôt qu’un accord automatique garde l’échange équilibré et amusant.')
