insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('530e8449-212d-45aa-8e97-70907690cac7', 'fr', 'Qu’est-ce qui rend ta façon de parler séductrice ?', '["Un rythme plus lent, sans précipitation", "Soutenir son regard pendant que tu parles", "Laisser les mots faire leur effet avec une petite pause", "Toutes les réponses ci-dessus"]'::jsonb, 'Le flirt vient du rythme et de la présence : ralentis, soutiens son regard et laisse les mots faire leur effet.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('545da6d1-d1bc-41b2-90a4-6fb6c5a2003c', 'fr', 'Qu’est-ce que le « regard » quand on flirte ?', '["Garder un bon contact visuel pendant toute la conversation", "Un regard voulu pour créer de la tension et montrer ton intérêt", "La regarder profondément dans les yeux pour montrer ton assurance"]'::jsonb, 'Quand on flirte, le regard montre l’intérêt par la présence, pas par la domination ou l’excès.')
