insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('56839c41-b051-44d1-8c8b-3c1fc53a0809', 'fr', 'Elle t’explique un sujet compliqué. Quel compliment passerait le mieux ?', '["« Tu l’as vraiment bien expliqué, c’était facile à suivre »", "« Tu es vraiment belle. »", "« Tu as l’air intelligente. »", "« Ta voix est vraiment agréable. »"]'::jsonb, 'Il porte précisément sur son choix et son effort, ce qui montre que tu as vraiment vu sa démarche.')
