insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('57ea4716-3a0a-4ae1-9b73-029195409a88', 'fr', 'Elle reste impliquée quand tu fais un petit pas vers elle. Qu’est-ce que ça indique ?', '["Feu vert : elle est à l’aise avec une distance plus courte", "Elle veut tout de suite plus d’espace", "Tu devrais reculer pour rester prudent", "C’est encore trop tôt dans l’échange"]'::jsonb, 'Si elle ne bouge pas ou se rapproche aussi, elle est à l’aise avec cette proximité.')
