insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6021e5f1-ba61-4cb2-82c5-d1977fcb9ef6', 'fr', 'Elle est détendue et parle doucement dans un café calme. À quoi ton énergie doit-elle s’accorder ?', '["Détendue et calme, avec un ton chaleureux", "Forte et animée pour lui donner de l’énergie", "Terne et fatiguée pour paraître nonchalant", "Forte pour couvrir le bruit ambiant"]'::jsonb, 'Accorde-toi à son humeur détendue pour créer un confort partagé et rester ajusté.')
