insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6581dc47-ce07-4d7a-a3fb-126a6b812a79', 'fr', 'Pourquoi la chaleur compte-t-elle quand tu fais preuve de culot ?', '["La chaleur évite que le culot passe pour de la vraie impolitesse", "Elle rend tes paroles plus claires, pour que les blagues soient bien comprises", "La chaleur aide à mieux se souvenir des conversations"]'::jsonb, 'La chaleur montre que les remarques culottées sont un jeu ; sans elle, les mêmes mots peuvent paraître impolis.')
