insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('67aef6c5-f235-4eb5-ad2b-86fb824c4b0a', 'fr', 'Tu remarques son style original pendant la conversation. Quelle est la meilleure façon de lui faire un compliment ?', '["Dire vite « Sympa, ton style ! » et passer à autre chose", "Utiliser des mots plus audacieux", "Faire un compliment général sans la regarder", "Adoucir ta voix, croiser son regard et dire : « Ton style se remarque vraiment. »"]'::jsonb, 'Une façon de dire posée et chaleureuse crée plus d’attirance qu’une politesse expédiée.')
