insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('71303602-cef7-48f0-9a80-8ba290228313', 'fr', 'Qu’apporte un regard soutenu ?', '["Il crée entre vous une tension qui va au-delà des mots", "Il montre ton intérêt sans le dire", "Il montre de l’assurance sociale"]'::jsonb, 'Le regard communique ton intérêt sans mots et sans forcer de réponse.')
