insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7c711059-22dd-4139-9523-2de1103e125a', 'fr', 'Que veut dire ajuster ton énergie ?', '["Toujours arriver avec beaucoup d’enthousiasme", "Imiter exactement, sans aucune variation", "Garder la même ambiance partout", "Te mettre au niveau de l’ambiance du moment ou la faire monter légèrement"]'::jsonb, 'Accorde-toi d’abord à l’énergie présente, puis fais-la monter légèrement si le moment s’y prête.')
