insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8b46401f-6a8e-4626-a152-9b226dc2e7bf', 'fr', 'Tu sens une bonne ambiance, mais tu hésites. Quel risque crée le fait d’attendre trop longtemps ?', '["Elle peut penser que tu n’es pas intéressé", "L’échange reste poli et neutre", "Tu laisses passer le moment naturel pour créer de la tension", "Toutes les réponses ci-dessus"]'::jsonb, 'Ces moments ne durent pas. La fenêtre est courte, mais elle compte.')
