insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8fde0458-59d3-43bb-9001-d87062672d85', 'fr', 'Avec les mêmes mots, quelle version a le plus de chances de créer une tension romantique ?', '["« Tu es vraiment drôle », dit vite, avant de passer au sujet suivant", "« Tu es vraiment drôle », dit en regardant quelqu’un d’autre", "« Tu es vraiment drôle », dit lentement, avec un regard chaleureux et une pause"]'::jsonb, 'Un rythme posé et de la présence donnent de l’intensité à la phrase, au lieu d’une simple politesse.')
