insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9307f2f7-e573-4a52-81e2-e255d0fe0983', 'fr', 'Une discussion de trois minutes se termine sur des rires, mais sans numéro. Comment dois-tu la voir ?', '["Un moment agréable et réussi", "Un échec complet", "Une occasion manquée de concrétiser", "Du temps perdu"]'::jsonb, 'Le but, c’est l’énergie positive partagée, pas les résultats secondaires.')
