insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('94b2a1ba-b2aa-42e8-bf7a-d35951d81430', 'fr', 'Tu abordes un groupe animé au bar. Quelle énergie marche ?', '["Apporter une énergie calme et détendue pour équilibrer leur bruit", "T’accorder à leur énergie animée avec un ton enjoué", "Dépasser légèrement leur énergie pour te démarquer positivement"]'::jsonb, 'Les gens réagissent le mieux à une énergie enjouée qui suit leur rythme.')
