insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a25d7cd3-3b21-4ccb-89ba-1cffbbe6a49d', 'fr', 'Pourquoi la répartie aide-t-elle à créer une alchimie romantique ?', '["Elle crée une tension légère et du jeu", "Elle réduit la distance émotionnelle grâce au rire", "Elle garde la conversation sérieuse et polie", "Elle crée une énergie d’aller-retour réciproque"]'::jsonb, 'Le jeu fait la différence entre le flirt et une simple complicité amicale.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a2f4b225-b8a7-4317-8f9e-d5d7ce3e0c73', 'fr', 'Quels comportements montrent une attention respectueuse ?', '["Continuer la conversation pour la faire changer d’avis", "Accepter « J’ai un copain » sans insister", "Prendre du recul quand elle donne des réponses courtes", "Mettre fin poliment à l’échange quand elle est peu impliquée"]'::jsonb, 'Le respect se voit à la vitesse à laquelle tu t’ajustes et à la propreté de ta sortie quand l’intérêt n’est pas là.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a621c77a-69b0-4f0a-8e2f-6e12dbf8bc0b', 'fr', 'Pourquoi ne pas être impressionné d’emblée crée-t-il de l’attirance ?', '["Ça montre que tu cherches son approbation", "Ça casse le schéma de l’accord automatique", "Ça la traite d’égal à égal au lieu de la mettre sur un piédestal"]'::jsonb, 'On passe d’une poursuite à une sélection mutuelle et équilibrée.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a64d80aa-89d6-4008-bb0c-2e3f3d44e8d8', 'fr', 'Qu’est-ce qui crée l’« étincelle » de la tension sexuelle ?', '["Une légère incertitude : est-ce plus qu’amical ?", "Tout garder prévisible et amical", "Déclarer clairement tes intentions romantiques dès le début", "Éviter toute conscience physique"]'::jsonb, 'La question « Est-ce que c’est plus que ça ? » garde l’attention en éveil.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a9af130c-ceeb-430c-817a-3b39ec63ff4b', 'fr', 'Qu’est-ce qui définit le mieux un petit défi quand on flirte ?', '["Un échange ludique qui crée de l’implication sans conséquences", "Un test pour voir à quel point elle est intelligente ou douée", "Une forme de taquinerie destinée à la mettre sur la sellette"]'::jsonb, 'Un petit défi, c’est un jeu partagé et sans danger. Il n’y a pas de vrai enjeu.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ac1764e4-0635-4b2a-a9b1-3d396b43c335', 'fr', 'Quels signaux montrent que tu peux te rapprocher un peu sans risque ?', '["Elle reste détendue quand tu te rapproches", "Elle se penche vers toi en parlant", "Elle soutient ton regard", "Elle regarde souvent autour d’elle dans la salle"]'::jsonb, 'Le confort se voit quand elle reste en place, te rend la pareille et reste détendue et impliquée.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('af902d35-dd20-4ecf-9ebd-6cc05bed06fb', 'fr', 'Pourquoi faut-il rompre la complicité pour créer de la tension sexuelle ?', '["Une complicité pure garde l’échange amical et prévisible", "La rupture fait naître la question d’une possibilité romantique", "Une complicité constante crée toujours de l’attirance"]'::jsonb, 'La tension vient du fait de suggérer plus qu’une amitié.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b39a64ab-2d91-47b4-9ea1-8646ba10c538', 'fr', 'Pourquoi éviter tout contact bloque-t-il souvent l’attirance ?', '["Ça paraît ennuyeux", "Ça rend l’échange purement amical", "Ça montre un manque d’assurance", "Ça ralentit la conversation"]'::jsonb, 'Sans progression physique, l’échange peut rester amical plutôt que séducteur.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b4ae1063-f21b-4c92-b4e9-ddeb53c5685f', 'fr', 'Elle s’appuie contre le bar en parlant. Comment l’imiter ?', '["Rester raide pour montrer ton assurance", "Copier tout de suite exactement sa position", "Te rapprocher pour aller plus loin", "Adopter progressivement une posture détendue semblable"]'::jsonb, 'Un accord discret crée de l’aisance sans paraître joué.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b4cb96a5-9dac-4da8-9559-0e356ea4eeeb', 'fr', 'Pourquoi un toucher ajusté crée-t-il efficacement de l’attirance ?', '["Il communique un intérêt romantique sans mots", "Il ajoute une dimension physique à un lien déjà là", "Il marche le mieux quand il est audacieux et fréquent"]'::jsonb, 'Un toucher voulu renforce l’alchimie quand il arrive au moment où elle est à l’aise.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b5aafcca-ae9a-48c1-974b-435701916b85', 'fr', 'Elle dit qu’elle est très douée pour lire les cartes. Quelle réponse de flirt pourrais-tu faire ?', '["« Alors tu peux m’indiquer le chemin jusqu’à ton cœur ? »", "« Tu devrais sûrement utiliser plus souvent un GPS. »", "« C’est prétentieux, haha »", "« Trouver son chemin, ce n’est pas si dur. »"]'::jsonb, 'L’humour séducteur crée de l’attirance en rebondissant sur ce qu’elle dit pour jouer.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b60b077a-0761-4330-9234-8fdcc1b81325', 'fr', 'Pourquoi le mimétisme corporel crée-t-il de la complicité à un niveau inconscient ?', '["Le cerveau perçoit un langage corporel accordé comme sûr, familier et digne de confiance", "Il montre que tu fais attention et que tu es impliqué avec elle", "Il montre de l’intelligence sociale et de la sensibilité émotionnelle"]'::jsonb, 'Le mimétisme signale inconsciemment la familiarité et l’aisance, ce qui favorise la complicité.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b70c5e9d-c782-4a54-be4f-ed860758730b', 'fr', 'Quels types de compliments sont les meilleurs ?', '["Son style, son humour ou le regard qu’elle porte sur les choses", "Ses efforts ou sa façon de s’impliquer", "Quelque chose qu’elle a choisi ou exprimé, pas dont elle a hérité", "Toutes les réponses ci-dessus"]'::jsonb, 'Un compliment touche le plus quand il porte sur ses choix, pas sur ses traits.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bc66a400-41a9-4f56-9e78-344908ee749c', 'fr', 'Pourquoi le toucher peut-il accélérer l’attirance plus que les mots seuls ?', '["Il crée un attachement physiologique et du confort", "Il court-circuite la pensée rationnelle", "Il montre ta domination", "Il prouve ton assurance"]'::jsonb, 'Le toucher active des réactions de confiance et d’attachement que les mots seuls ne peuvent pas créer.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bd77420f-f0c3-434d-a194-ed4c67dc0f59', 'fr', 'Elle se retire légèrement après un toucher léger sur le bras. Que dois-tu faire ?', '["Lui laisser de l’espace et continuer sans autre contact", "La toucher de nouveau pour montrer ton assurance", "T’excuser et demander la permission la prochaine fois", "Passer à un autre type de toucher"]'::jsonb, 'Respecte sa réaction en mettant en pause toute progression physique.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c23fa6ee-381a-4d27-bf59-41f86d51451f', 'fr', 'Elle te taquine gentiment et rit. Que pourrais-tu dire pour faire basculer le moment ?', '["« Tes yeux s’illuminent vraiment quand tu ris, j’aime bien »", "« Tu es drôle. »", "« Bien joué. »", "« Tu gagnes cette manche. »"]'::jsonb, 'Un ton doux et une observation précise suggèrent l’attirance sans lourdeur.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c595ee3e-bb2d-4d31-8268-40919fdef131', 'fr', 'Elle se vante pour jouer d’être très compétitive au tennis. Que pourrais-tu dire ?', '["« Ce n’est pas toujours une bonne chose. »", "« J’adore les défis. Juste, ne pleure pas quand je gagnerai. »", "« La compétition, c’est malsain. »", "« Raconte-moi. »"]'::jsonb, 'Accorde-toi à son côté joueur pour faire monter la répartie et l’énergie.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c98b4016-8474-4fa7-b00d-224a8135153a', 'fr', 'Quelle phrase à te rappeler t’aide le mieux à avoir le bon état d’esprit avant d’aborder ?', '["« Il faut que je me démarque »", "« Ce soir, je pourrais avoir de la chance »", "« Il faut que je sois sûr de moi »", "« Mon but est de créer un bon moment »"]'::jsonb, 'Cet état d’esprit te garde ancré, présent et sans pression.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cbbc6dae-7dab-4dde-93eb-57bc3de19179', 'fr', 'Lequel de ces exemples n’est pas une bonne façon d’utiliser un petit défi amusant ?', '["Deviner ce qu’elle prend au café", "Lui demander de départager deux options et de choisir son camp", "L’interroger sur quelque chose qu’elle ne connaît pas", "Transformer une question en devinette ludique"]'::jsonb, 'Un défi ne doit jamais la mettre dans une position où elle se sent nulle. Le but, c’est de s’amuser.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cde2d207-7899-48ff-a104-fbf28135a2b2', 'fr', 'Quels signes montrent qu’elle est à l’aise avec une plus grande proximité ?', '["Elle reste impliquée quand tu te rapproches", "Elle se penche ou se déplace vers toi", "Elle soutient ton regard pendant toute la conversation"]'::jsonb, 'Le confort se voit quand elle reste en place, te rend la pareille et reste détendue et impliquée.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ce4b3a53-6296-4e5e-9208-4ef8f7666fd8', 'fr', 'Quel état d’esprit aide à bien utiliser le regard ?', '["« Il faut que je l’impressionne »", "« Je dois éviter la gêne »", "« Je suis à l’aise quand on me regarde »", "« Il faut que je dise quelque chose de malin »"]'::jsonb, 'Un regard qui crée de la tension vient de l’aisance à être présent, pas de la performance.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cebe76a8-b37d-42fc-a5ff-e7a9ecc85c3c', 'fr', 'Tu commences à flirter avec une femme dans un bar. Quel doit être ton but principal ?', '["Obtenir son numéro ou la ramener chez toi ce soir", "Créer un moment amusant et agréable, maintenant", "L’impressionner avec des compliments et de la tension", "Prouver que tu es sûr de toi et que tu en vaux la peine"]'::jsonb, 'Un flirt est réussi quand le moment devient plus léger et plus vivant, quel que soit le résultat.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d1e81b89-292c-47d2-881c-2ead24b571e1', 'fr', 'Pourquoi les compliments sur les efforts ou la façon de s’exprimer marchent-ils mieux que les compliments sur le physique ?', '["Ils paraissent plus intellectuels", "Ils mettent moins de pression et paraissent plus personnels", "Ils te rendent plus intéressant", "Ils sont plus difficiles à faire"]'::jsonb, 'Les compliments qui reconnaissent des choix et des efforts paraissent plus sûrs et créent plus de lien.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d5e4ef95-c1aa-4bd2-a5ca-49fc6afba2c8', 'fr', 'Lesquels de ces comportements peuvent faire décrocher les gens ?', '["Un langage corporel neutre", "Poser des questions simples", "Les conversations courtes", "Apporter une énergie faible ou pesante"]'::jsonb, 'On s’éloigne instinctivement des humeurs qui épuisent.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e1d057ce-7c4d-495e-b2d7-fcc87a1c4105', 'fr', 'Elle dit : « Je suis très difficile avec les mecs. » Que pourrais-tu répondre pour montrer que tu n’es pas impressionné d’emblée ?', '["« Tant mieux, tu as raison. »", "« C’est quoi, ton genre ? »", "« Je vais essayer d’être à la hauteur. »", "« Parfait, parce que moi aussi, je suis difficile. »"]'::jsonb, 'Retourner la situation pour jouer montre que tu as des exigences et crée un équilibre, sans chercher son approbation.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e7cbc051-5503-4e4c-b6fd-0a4dea2be140', 'fr', 'Elle partage une solution créative à un problème. Quel compliment passerait le mieux ?', '["« Tu es superbe. »", "« C’est vraiment malin comme approche. Je n’y aurais pas pensé. »", "« Tu es tellement intelligente. »", "« Ta voix est apaisante. »"]'::jsonb, 'Il porte sur son choix créatif, et elle se sent vue pour sa façon de penser.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e91466f0-24f3-4932-ab70-eab86651982c', 'fr', 'Quelles zones sont généralement sûres pour un premier toucher ajusté ?', '["L’avant-bras", "L’épaule", "Le haut du bras", "La taille ou les hanches"]'::jsonb, 'Un premier toucher doit rester non intime et adapté à la situation.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ea410aea-176d-48e3-8281-7a8a1353ca46', 'fr', 'L’ambiance est super, mais il n’y a pas encore eu de contact. Elle te touche légèrement le bras. Que pourrais-tu faire ?', '["L’ignorer et garder tes distances", "Faire une remarque sur son geste", "La toucher tout de suite davantage", "Lui rendre un toucher léger plus tard, à un moment naturel"]'::jsonb, 'Réponds progressivement à son signal pour rester dans un confort partagé.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ebdbe221-f51b-4b0c-bd4b-aae266f0bcb8', 'fr', 'Pourquoi les rappels augmentent-ils l’attirance ?', '["Ils montrent ta domination", "Ils montrent ton intelligence", "Ils réduisent l’effort dans la conversation", "Ils montrent ton attention et créent de la familiarité"]'::jsonb, 'Quand on se souvient de nous, on se sent vu, ce qui renforce l’aisance et le lien.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ec7b6208-0886-41d6-bcde-5876126e4cad', 'fr', 'Quelles qualités rendent un regard attirant plutôt que gênant ?', '["La chaleur", "Une posture détendue", "Un rythme calme", "La fixer intensément"]'::jsonb, 'La tension vient de l’aisance et de la présence, pas de la pression.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('efb89d58-f624-4e43-8edf-0cee0dad7d5c', 'fr', 'Quelles sont les caractéristiques d’une bonne énergie ?', '["Chaleureuse", "Ancrée", "Légèrement enjouée", "Intense et dominante"]'::jsonb, 'Une bonne énergie paraît accueillante et rassurante, pas écrasante ni épuisante.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f23233f3-ec06-4834-bf59-d052a683bed7', 'fr', 'Quels comportements peuvent créer de la tension sexuelle sans mots ?', '["Soutenir son regard un instant de plus", "Te tenir un peu plus près à mesure que la complicité grandit", "Enchaîner les questions pour garder l’élan", "Laisser durer un peu un contact quand elle te le rend"]'::jsonb, 'Des signaux non verbaux qui sortent subtilement du registre amical ouvrent une possibilité.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f442e1ff-0765-4613-91d3-e838e3234d98', 'fr', 'Qu’est-ce qu’une bonne énergie quand on flirte ?', '["Un ton chaleureux et posé", "Enjouée sans être écrasante", "Plate et neutre pour éviter les erreurs", "Légèrement au-dessus de l’humeur du moment"]'::jsonb, 'Une bonne énergie fait monter l’ambiance et rend les autres plus vivants.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f5266e4f-abf4-4ecb-b84d-f1a01c78df7c', 'fr', 'Qu’est-ce qui fait passer le plus sûrement un compliment de « gentil » à « désir » ?', '["Des mots plus intenses", "Des détails plus précis sur sa tenue", "Le ton, le regard et le rythme", "Le dire plus fort"]'::jsonb, 'Les mêmes mots peuvent paraître amicaux ou chargés selon la façon de les dire.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f6cb6b9f-3832-422f-a15d-ba9827f8dbf8', 'fr', 'Elle recule légèrement après que tu t’es rapproché. Que dois-tu faire ensuite ?', '["Te rapprocher de nouveau pour montrer ton assurance", "Mettre fin à la conversation", "Lui demander si elle est mal à l’aise", "Lui laisser plus d’espace et continuer calmement"]'::jsonb, 'Respecte son signal en reprenant de la distance pour préserver son confort et sa confiance.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f6feba7a-6f51-4a47-b8a8-d65c8f9ea942', 'fr', 'Tu la guides dans un endroit bondé. Quel toucher est approprié ?', '["Aucun toucher n’est nécessaire", "Le bras autour de ses épaules", "Un toucher léger sur son bras pour la guider"]'::jsonb, 'Un geste bref et pratique pour la guider correspond au contexte et crée de l’aisance.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f798a3d2-77df-4e98-b5f6-850a383b86e9', 'fr', 'Pourquoi un mimétisme discret crée-t-il efficacement de la complicité ?', '["Il signale inconsciemment la sécurité et la compatibilité", "Il lui donne l’impression que tu es familier et digne de confiance", "Il communique une ressemblance sans mots", "Toutes les réponses ci-dessus"]'::jsonb, 'Le mimétisme signale inconsciemment la familiarité et l’aisance, ce qui favorise la complicité.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f7b1d87a-9566-45e6-a098-77d7a9c2ebaf', 'fr', 'Elle s’assoit, et toi, tu restes debout au-dessus d’elle. Que pourrais-tu faire pour mieux t’accorder à elle ?', '["Lui demander si tu peux t’asseoir aussi pour être à la même hauteur", "Rester debout pour garder une posture assurée", "Te pencher légèrement pour être à hauteur de ses yeux"]'::jsonb, 'Se mettre à la même hauteur réduit le déséquilibre et crée inconsciemment de l’aisance.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f7dc51a9-b997-4ed3-a54b-5996a6886069', 'fr', 'Pourquoi est-on naturellement attiré par une énergie positive ?', '["Les gens chaleureux sont naturellement plus attirants et charismatiques", "On protège son état émotionnel : on cherche ce qui fait du bien et on évite ce qui épuise", "Une énergie entraînante signale de l’assurance et un statut social"]'::jsonb, 'On va vers ce qui fait du bien et on s’éloigne de ce qui ne nous en fait pas.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('fabb2d4d-834e-4aed-9716-9cafe7b3c118', 'fr', 'Elle passe d’une position bien droite à appuyée contre le bar. Meilleure réaction ?', '["Rester bien droit : un mimétisme trop visible, c’est gênant", "Lui demander si elle est fatiguée, puisqu’elle s’appuie maintenant", "T’appuyer aussi, naturellement, pour suivre son changement de posture général"]'::jsonb, 'Un accord discret crée de l’aisance sans paraître joué.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('fbd08cf5-bc99-4004-98d5-438bd2be4a9c', 'fr', 'Quelles formes de mimétisme sont efficaces ?', '["Prendre une posture ou une position semblable à la sienne", "Copier tout de suite chacun de ses petits gestes", "Accorder ton énergie et ton rythme aux siens", "Ajuster ton volume au sien"]'::jsonb, 'Le mimétisme signale inconsciemment la familiarité et l’aisance, ce qui favorise la complicité.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
